  rect(player.x, player.y, player.w, player.h);

  // Charge indicator bar
  if (player.state === 1) {
    fill(255, 0, 0);
    rect(player.x, player.y - 8, player.w * chargeRatio, 4);
  }

  pop();

  // HUD: Progress bar on the right edge
